begin;
select no_plan();
insert into auth.users(id,aud,role,email) values
 ('00000000-0000-4000-8000-000000000111','authenticated','authenticated','policy-owner@example.invalid'),
 ('00000000-0000-4000-8000-000000000112','authenticated','authenticated','policy-manager@example.invalid');
insert into public.ten29_admins(user_id,role) values('00000000-0000-4000-8000-000000000111','OWNER'),('00000000-0000-4000-8000-000000000112','MANAGER');
create temporary table f(r uuid,q uuid,s uuid,d uuid,e uuid,k uuid default gen_random_uuid());
grant all on f to authenticated;
insert into f default values;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000111',true);
insert into public.booking_requests(id,source,package_code,check_in_date,check_out_date,overnight_guest_count)
values('00000000-0000-4000-8000-000000000119','PHONE','WHOLE_HOME_1BR','2049-01-01','2049-01-02',2);
select is((select policy_version from public.booking_requests where id='00000000-0000-4000-8000-000000000119'),'LEGACY','historic semantics explicitly legacy');
select is((select countable_guest_count from public.booking_requests where id='00000000-0000-4000-8000-000000000119'),null::smallint,'no historic age-band inference');
update f set r=public.perform_booking_operation('MANUAL',null,gen_random_uuid(),'{"source":"PHONE","package_code":"WHOLE_HOME_3BR","check_in_date":"2049-02-01","check_out_date":"2049-02-03","overnight_guest_count":8,"folding_foams_requested":true,"policy_version":"TEN29-20261015-v1","adults_count":7,"older_children_count":0,"exempt_children_count":1,"full_name":"Synthetic Policy Guest","contact_number":"555-0100","email":"","notes":""}');
select is((select countable_guest_count::int from public.booking_requests where id=(select r from f)),7,'countable seven');
select is((select overnight_guest_count::int from public.booking_requests where id=(select r from f)),8,'actual eight');
select is((select exempt_children_count::int from public.booking_requests where id=(select r from f)),1,'toddler recorded');
select is((select extra_guests_requested::int from public.booking_requests where id=(select r from f)),1,'one extra requested');
select throws_ok($$update public.booking_requests set exempt_children_count=0 where id=(select r from f)$$,'23514',null,'cannot hide young occupants');
select throws_ok($$insert into public.booking_requests(source,package_code,check_in_date,check_out_date,overnight_guest_count,folding_foams_requested,policy_version,adults_count,older_children_count,exempt_children_count,countable_guest_count,extra_guests_requested,occupancy_owner_review) values('PHONE','WHOLE_HOME_1BR','2049-03-01','2049-03-02',4,true,'TEN29-20261015-v1',4,0,0,4,2,false)$$,'23514',null,'1BR cannot exceed three countable guests');
select lives_ok($$insert into public.booking_requests(source,package_code,check_in_date,check_out_date,overnight_guest_count,folding_foams_requested,policy_version,adults_count,older_children_count,exempt_children_count,countable_guest_count,extra_guests_requested,occupancy_owner_review) values('PHONE','WHOLE_HOME_1BR','2049-03-01','2049-03-02',4,true,'TEN29-20261015-v1',3,0,1,3,1,false)$$,'1BR three countable plus exempt toddler');
select lives_ok($$insert into public.booking_requests(source,package_code,check_in_date,check_out_date,overnight_guest_count,folding_foams_requested,policy_version,adults_count,older_children_count,exempt_children_count,countable_guest_count,extra_guests_requested,occupancy_owner_review) values('PHONE','WHOLE_HOME_2BR','2049-03-01','2049-03-02',6,true,'TEN29-20261015-v1',5,0,1,5,1,false)$$,'2BR five countable plus exempt toddler');
select lives_ok($$select public.perform_booking_operation('STATUS',r,gen_random_uuid(),'{"status":"REVIEWING","expected_status":"NEW"}') from f$$,'review before quote');
select throws_ok($$select public.prepare_itemized_booking_quote(r,null,null,'[]','[{"date":"2049-02-01","amount_centavos":10005,"reason":"Synthetic manual"},{"date":"2049-02-02","amount_centavos":10005,"reason":"Synthetic manual"}]',null,null,null,gen_random_uuid()) from f$$,'23514','OWNER occupancy approval required','extra request is not approval');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000112',true);
select throws_ok($$select public.perform_booking_policy_operation(r,gen_random_uuid(),'{"type":"EXTRA_APPROVE","count":1,"occupancy_reviewed":true}') from f$$,'42501',null,'manager cannot approve extras');
select is((select count(*)::int from public.booking_policy_events),0,'manager cannot read policy events');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000111',true);
update f set e=public.perform_booking_policy_operation(r,k,'{"type":"EXTRA_APPROVE","count":1,"occupancy_reviewed":true}');
select is((select public.perform_booking_policy_operation(r,k,'{"type":"EXTRA_APPROVE","count":1,"occupancy_reviewed":true}') from f),(select e from f),'exact approval retry');
select throws_ok($$select public.perform_booking_policy_operation(r,k,'{"type":"EXTRA_APPROVE","count":2,"occupancy_reviewed":true}') from f$$,'23514','Policy operation key conflict','approval key binds full payload');
update f set q=public.prepare_itemized_booking_quote(r,null,null,'[]','[{"date":"2049-02-01","amount_centavos":10005,"reason":"Synthetic manual"},{"date":"2049-02-02","amount_centavos":10005,"reason":"Synthetic manual"}]',null,null,null,gen_random_uuid());
select is((select (public.read_owner_quote_breakdown(q)->>'final_total_centavos')::bigint from f),100010::bigint,'extra amount one times 40000 times two nights');
select is((select (public.read_owner_quote_breakdown(q)->'payment'->>'required_down_payment_centavos')::bigint from f),30003::bigint,'30 percent exact cents');
select is((select (public.read_owner_quote_breakdown(q)->'payment'->>'remaining_required_centavos')::bigint from f),70007::bigint,'70 percent remainder');
select is((select (public.read_owner_quote_breakdown(q)->'payment'->>'refundable_security_deposit_centavos')::bigint from f),200000::bigint,'security separate from quote revenue');
select throws_ok($$select public.issue_itemized_booking_quote(q) from f$$,'23514','Final OWNER payment authorization required','draft approval does not authorize payment amounts');
select throws_ok($$select public.prepare_itemized_booking_quote(r,null,null,'[{"type":"CHARGE","description":"Extra guest","quantity":1,"unit_amount_centavos":40000,"reason":"Duplicate"}]','[]',null,null,null,gen_random_uuid()) from f$$,'23514',null,'duplicate extra fee blocked');
select public.perform_booking_policy_operation(q,gen_random_uuid(),'{"type":"QUOTE_AUTHORIZE","basis_approved":true,"terms_communicated":true,"boundary_reviewed":true}') from f;
select public.issue_itemized_booking_quote(q) from f;
select throws_ok($$update public.booking_quotes set amount_total=1 where id=(select q from f)$$,'23514',null,'issued amount immutable');
select public.perform_booking_operation('STATUS',r,gen_random_uuid(),'{"status":"AWAITING_DEPOSIT","expected_status":"QUOTED"}') from f;
update f set d=public.perform_booking_operation('PAYMENT',r,gen_random_uuid(),'{"amount_centavos":30003,"payment_method":"GCASH","masked_reference":""}');
select throws_ok($$select public.confirm_booking_reservation(r,q,gen_random_uuid()) from f$$,'23514','Required down payment has not been independently verified','recorded receipt not verified');
select public.decide_booking_deposit(d,'VERIFIED',true,gen_random_uuid()) from f;
update f set s=public.confirm_booking_reservation(r,q,gen_random_uuid());
select is((select overnight_guest_count::int from public.booking_reservations where id=(select s from f)),8,'confirmation actual headcount snapshot');
select throws_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"RULES","status":"SENT_EXTERNALLY","genuinely_evidenced":true,"contents":"Forbidden"}') from f$$,'23514',null,'rules content field denied');
select throws_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"RULES","status":"ACKNOWLEDGED_BY_GUEST","genuinely_evidenced":true}') from f$$,'23514',null,'ack requires delivered status');
update f set k=gen_random_uuid(),e=public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"RULES","status":"SENT_EXTERNALLY","genuinely_evidenced":true}');
select is((select data from public.booking_policy_events where id=(select e from f)),'{"status":"SENT_EXTERNALLY"}'::jsonb,'rules store only status metadata');
select lives_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"RULES","status":"ACKNOWLEDGED_BY_GUEST","genuinely_evidenced":true}') from f$$,'owner evidenced acknowledgement');
update f set e=public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"SECURITY_RECORD","amount_centavos":200000,"method":"GCASH"}');
select is((select (public.read_owner_quote_breakdown(q)->>'verified_payments_centavos')::bigint from f),30003::bigint,'security excluded from accommodation ledger');
select public.perform_booking_policy_operation(s,gen_random_uuid(),jsonb_build_object('type','SECURITY_VERIFY','event_id',e,'independent',true)) from f;
select throws_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),jsonb_build_object('type','SECURITY_VERIFY','event_id',e,'independent',true)) from f$$,'23505',null,'security verification once');
select throws_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"SECURITY_REFUND_AUTHORIZE","deduction_centavos":0,"refund_centavos":200000,"reason":"OWNER_EXCEPTION"}') from f$$,'23514',null,'inspection required for security refund');
select lives_ok($$select public.perform_booking_operation('PAYMENT',r,gen_random_uuid(),'{"amount_centavos":70007,"payment_method":"BANK_TRANSFER","masked_reference":""}') from f$$,'balance can be recorded after confirmation');
update f set d=(select id from public.booking_deposits where request_id=f.r and amount=700.07);
select lives_ok($$select public.decide_booking_deposit(d,'VERIFIED',true,gen_random_uuid()) from f$$,'owner independently verifies remaining balance');
select is((select (public.read_owner_quote_breakdown(q)->>'remaining_balance_centavos')::bigint from f),0::bigint,'full accommodation settled without security inflating revenue');
select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"RESCHEDULE_REQUEST","check_in_date":"2049-05-01","check_out_date":"2049-05-03"}') from f;
select throws_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"RESCHEDULE_REQUEST","check_in_date":"2049-06-01","check_out_date":"2049-06-03"}') from f$$,'23505',null,'once-only request');
select is((select count(*)::int from public.property_occupancies where active and reservation_id=(select s from f)),1,'reschedule cannot release original occupancy');
select public.perform_booking_operation('CANCEL',s,gen_random_uuid(),'{"reason":"Synthetic owner cancellation","refund_review_acknowledged":true}') from f;
select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"CANCELLATION_REVIEW","classification":"NORMAL","refund_centavos":50005,"forfeit_centavos":50005,"credit_centavos":0,"credit_start":null,"credit_end":null,"processing_centavos":0,"basis":"VERIFIED_ACCOMMODATION","final":true}') from f;
select throws_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"ACCOMMODATION_REFUND_SENT","amount_centavos":100010,"independent":true}') from f$$,'23514',null,'refund cannot exceed owner authorization');
select lives_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"ACCOMMODATION_REFUND_SENT","amount_centavos":50005,"independent":true}') from f$$,'actual manual settlement recorded');
select is((select (public.read_owner_quote_breakdown(q)->>'final_total_centavos')::bigint from f),100010::bigint,'cancellation leaves historical quote unchanged');
select is((select count(*)::int from public.booking_policy_events where type='SECURITY_REFUND_SENT'),0,'accommodation refund does not settle security');

select throws_ok($$select public.perform_booking_operation('NOTE',r,gen_random_uuid(),'{"text":"House Rules document"}') from f$$,'23514','House Rules contents and copies must remain outside TEN29','explicit rule copy rejected before note persistence');
select throws_ok($$select public.owner_media_action('RESERVE',null,null,jsonb_build_object('key',gen_random_uuid(),'mime','application/pdf','bytes',100))$$,'P0001','Unsupported type','document MIME cannot enter property-media storage');
select throws_ok($$select public.owner_media_action('RESERVE',null,null,jsonb_build_object('key',gen_random_uuid(),'mime','image/png','bytes',100,'house_rules','Forbidden'))$$,'23514','Only property photo/video uploads are supported','unexpected media document payload rejected');
select throws_ok($$select public.perform_booking_policy_operation(r,gen_random_uuid(),'{"type":"RULES","status":"SENT_EXTERNALLY","genuinely_evidenced":true}') from f$$,'23514',null,'request reference cannot forge confirmed external delivery');
update f set r=public.perform_booking_operation('MANUAL',null,gen_random_uuid(),'{"source":"PHONE","package_code":"WHOLE_HOME_1BR","check_in_date":"2000-01-01","check_out_date":"2000-01-02","overnight_guest_count":3,"folding_foams_requested":false,"policy_version":"TEN29-20261015-v1","adults_count":2,"older_children_count":0,"exempt_children_count":1,"full_name":"Synthetic Mature Stay","contact_number":"555-0100","email":"","notes":""}');
select public.perform_booking_operation('STATUS',r,gen_random_uuid(),'{"status":"REVIEWING","expected_status":"NEW"}') from f;
select throws_ok($$select public.prepare_itemized_booking_quote(r,null,3000,'[]','[{"date":"2000-01-01","amount_centavos":10000,"reason":"Synthetic mature stay"}]',null,null,null,gen_random_uuid()) from f$$,'23514','Review required payment schedule','short-notice quote rejects partial down payment');
update f set q=public.prepare_itemized_booking_quote(r,null,null,'[]','[{"date":"2000-01-01","amount_centavos":10000,"reason":"Synthetic mature stay"}]',null,null,null,gen_random_uuid());
select is((select public.read_owner_quote_breakdown(q)->'payment'->>'mode' from f),'FULL_PAYMENT','short notice requires full payment');
select is((select (public.read_owner_quote_breakdown(q)->>'final_total_centavos')::bigint from f),10000::bigint,'exempt child has no additional charge');
select public.perform_booking_policy_operation(q,gen_random_uuid(),'{"type":"QUOTE_AUTHORIZE","basis_approved":true,"terms_communicated":true,"boundary_reviewed":true}') from f;
select public.issue_itemized_booking_quote(q) from f;
select public.perform_booking_operation('STATUS',r,gen_random_uuid(),'{"status":"AWAITING_DEPOSIT","expected_status":"QUOTED"}') from f;
update f set d=public.perform_booking_operation('PAYMENT',r,gen_random_uuid(),'{"amount_centavos":3000,"payment_method":"BANK_TRANSFER","masked_reference":""}');
select public.decide_booking_deposit(d,'VERIFIED',true,gen_random_uuid()) from f;
select throws_ok($$select public.confirm_booking_reservation(r,q,gen_random_uuid()) from f$$,'23514','Required down payment has not been independently verified','30 percent verified cannot confirm full-payment quote');
update f set d=public.perform_booking_operation('PAYMENT',r,gen_random_uuid(),'{"amount_centavos":7000,"payment_method":"BANK_TRANSFER","masked_reference":""}');
select public.decide_booking_deposit(d,'VERIFIED',true,gen_random_uuid()) from f;
update f set s=public.confirm_booking_reservation(r,q,gen_random_uuid());
select public.perform_booking_operation('COMPLETE',s,gen_random_uuid(),'{"reason":"Synthetic checkout passed","refund_review_acknowledged":false}') from f;
update f set e=public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"SECURITY_RECORD","amount_centavos":150000,"method":"BANK_TRANSFER"}');
select public.perform_booking_policy_operation(s,gen_random_uuid(),jsonb_build_object('type','SECURITY_VERIFY','event_id',e,'independent',true)) from f;
select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"INSPECTION","status":"DEDUCTIONS_REVIEW"}') from f;
select throws_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"SECURITY_REFUND_AUTHORIZE","deduction_centavos":10000,"refund_centavos":150000,"reason":"PROPERTY_DAMAGE"}') from f$$,'23514',null,'deductions and refund must allocate verified collection exactly');
select lives_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"SECURITY_REFUND_AUTHORIZE","deduction_centavos":10000,"refund_centavos":140000,"reason":"PROPERTY_DAMAGE"}') from f$$,'owner approves inspected deduction and security refund');
select is((select count(*)::int from public.booking_policy_events where reservation_id=(select s from f) and type='SECURITY_REFUND_SENT'),0,'authorized refund is not actual settlement');
select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"SECURITY_REFUND_SENT","amount_centavos":140000,"independent":true}') from f;
select throws_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"SECURITY_REFUND_SENT","amount_centavos":1,"independent":true}') from f$$,'23514',null,'no security over-refund');
select is((select (public.read_owner_quote_breakdown(q)->>'verified_payments_centavos')::bigint from f),10000::bigint,'security collection/deduction/refund remains separate from accommodation');
select throws_ok($$select public.perform_booking_policy_operation(s,gen_random_uuid(),'{"type":"RULES","status":"SENT_EXTERNALLY","genuinely_evidenced":true}') from f$$,'23514',null,'completed stay cannot fabricate delivery');
select * from finish();
rollback;
